  // ---- Rank Perks (RP = rank ‡∏ó‡∏±‡πâ‡∏á‡∏´‡∏°‡∏î ¬∑ ‡πÉ‡∏ä‡πâ‡πÑ‡∏õ‡∏ï‡∏≤‡∏°‡∏ó‡∏µ‡πà‡∏•‡∏á perk) ----
  perkLvl(id){ return (this.data.rankPerks||{})[id]||0; },
